const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Define the administrative boundaries for Punjab and Haryana, India.
    const adminBoundaries = ee.FeatureCollection('FAO/GAUL/2015/level1');
    const punjab = adminBoundaries.filter(ee.Filter.inList('ADM1_NAME', ['Punjab']));
    const haryana = adminBoundaries.filter(ee.Filter.inList('ADM1_NAME', ['Haryana']));
    const geometry = punjab.merge(haryana).union();

    const targetYear = 2024;
    const comparisonStartYear = 2012;
    const comparisonEndYear = 2023;
    const month = 11;

    // 2. Data Acquisition & Processing
    const firms = ee.ImageCollection('FIRMS').select('T21'); // FIRMS dataset includes VIIRS data.

    const fireCounts = {};

    // Asynchronous function to get fire count for a given year
    async function getFireCount(year) {
        const startDate = ee.Date.fromYMD(year, month, 1);
        const endDate = startDate.endOfMonth();
        const collection = firms.filterDate(startDate, endDate).filterBounds(geometry);
        const count = collection.size().getInfo();
        return count;
    }

    try {
        // As of the current date, data for November 2024 does not exist.
        // Therefore, we can immediately conclude the collection for 2024 will be empty.
        const currentServerTime = ee.Date(Date.now());
        const targetDate = ee.Date.fromYMD(targetYear, month, 1);

        if (currentServerTime.millis().getInfo() < targetDate.millis().getInfo()) {
            console.log(`Evidence: Data for November ${targetYear} is not yet available.`);
            console.log(`Count for Nov ${targetYear}: 0`);
            console.log("This is an anticipated failure as the time period is in the future.");
            console.log('A: No');
            return;
        }

        // This block would run if the script were executed after November 2024
        const targetCount = await getFireCount(targetYear);
        fireCounts[targetYear] = targetCount;

        if (targetCount === 0 && (await firms.filterDate(ee.Date.fromYMD(targetYear, month, 1), ee.Date.fromYMD(targetYear, month, 1).endOfMonth()).size().getInfo()) === 0) {
             console.log(`No images found for the target period: November ${targetYear}.`);
             console.log('C1');
             return;
        }

        const comparisonCounts = [];
        for (let year = comparisonStartYear; year <= comparisonEndYear; year++) {
            const count = await getFireCount(year);
            fireCounts[year] = count;
            comparisonCounts.push(count);
            console.log(`Fire count for Nov ${year}: ${count}`);
        }

        const minComparisonCount = Math.min(...comparisonCounts);

        console.log(`\nTarget period count (Nov ${targetYear}): ${targetCount}`);
        console.log(`Minimum comparison period count (Nov ${comparisonStartYear}-${comparisonEndYear}): ${minComparisonCount}`);

        if (targetCount < minComparisonCount) {
            console.log('A: Yes');
        } else {
            console.log('B: No');
        }

    } catch (e) {
        console.error(`An error occurred: ${e.message}`);
        console.log('D');
    }
}

